body:
> In a release build, f-strings are a bit slower than concatenation or percent formatting, but much faster than String.format() (even when String.format() takes in a constant array as parameter). I'm surprised String.format() is so slow here – it might be worth investigating on its own.

I think this is due to constant values/operators getting optimized out for the other cases, while `String.format()` might need to be left in in case the function call has side effects.

I tried benchmarking with the gdscript below:

```gdscript
var text := "Hello world!"
func _ready() -> void:
	run_test("string_concat")
	run_test("sprintf")
	run_test("format_indexed")
	run_test("format_non_indexed")
	run_test("fstring")
	
func run_test(p_name : String):
	var start := Time.get_ticks_msec()
	call(p_name)
	var end := Time.get_ticks_msec()
	print("%s: %dms" % [p_name, end - start])

func string_concat():
	for i in 1000000:
		"Result: " + text
		
func sprintf():
	for i in 1000000:
		"Result: %s" % text

func format_indexed():
	var args := [text]
	for i in 1000000:
		"Result: {0}".format(args)

func format_non_indexed():
	var args := [text]
	for i in 1000000:
		"Result: {}".format(args, "{}")

func fstring():
	for i in 1000000:
		f"Result: {text}"
```

Results:
```
string_concat: 212ms
sprintf: 813ms
format_indexed: 761ms
format_non_indexed: 450ms
fstring: 985ms
```

Not sure about the difference between `format_indexed` and `fstring`, but compiling fstrings to something like the non-indexed case might be worth it if it's not too big a change.  If we do go with that, it might be safer to use something besides `{}` for the placeholder argument - I think it's ok currently, but would depend on the current `Dictionary` -> `String` behavior of using `{  }` for empty dictionaries instead of `{}`

Updated benchmarks below.  Looks like the const handling is faster, but still creating the argument array each time - added some comments above

```gdscript
var text := "Hello world!"
func _ready() -> void:
	run_test("string_join")
	run_test("string_concat")
	run_test("sprintf")
	run_test("format_indexed")
	run_test("format_non_indexed")
	run_test("fstring")
	run_test("fstring_const")
	
func run_test(p_name : String):
	var start := Time.get_ticks_msec()
	call(p_name)
	var end := Time.get_ticks_msec()
	print("%s: %dms" % [p_name, end - start])

func string_join():
	for i in 1000000:
		"".join(["Result: ", text])
		
func string_concat():
	for i in 1000000:
		"Result: " + text
		
func sprintf():
	for i in 1000000:
		"Result: %s" % text

func format_indexed():
	for i in 1000000:
		"Result: {0}".format([text])

func format_non_indexed():
	for i in 1000000:
		"Result: {}".format([text], "{}")

func fstring():
	for i in 1000000:
		f"Result: {text}"
	
func fstring_const():
	const const_text = "Hello world!"
	for i in 1000000:
		f"Result: {const_text}"
```

Results:
```
string_join: 578ms
string_concat: 137ms
sprintf: 839ms
format_indexed: 942ms
format_non_indexed: 638ms
fstring: 594ms
fstring_const: 230ms
```
